from collections import defaultdict

class Tally:
    def __init__(self, iterable=None):
        self._counts = defaultdict(int)
        for item in iterable or []:
            self._counts[item] += 1

    def count(self, key, delta=1):
        self._counts[key] += delta
        return self._counts[key]

    def get(self, key):
        return self._counts[key]

    def most_common(self, n=None):
        items = sorted(self._counts.items(), key=lambda kv: (-kv[1], str(kv[0])))
        return items if n is None else items[:n]

t = Tally('banana')
print(t.get('a'), t.get('z'), t.most_common(2))

class Counter:
    def __init__(self, **counts):
        self._counts = dict(counts)

    def __getitem__(self, key):
        return self._counts.get(key, 0)

    def __setitem__(self, key, value):
        if value < 0:
            raise ValueError('count cannot be negative')
        self._counts[key] = value

    def __contains__(self, key):
        return key in self._counts

    def increment(self, key, delta=1):
        self._counts[key] = self[key] + delta

    def decrement(self, key, delta=1):
        if self[key] - delta < 0:
            raise ValueError('count would become negative')
        self._counts[key] = self[key] - delta

