class ShoppingCart:
    def __init__(self, prices):
        self.prices = prices
        self.items = {}

    def add(self, name, qty=1):
        if name not in self.prices:
            raise KeyError(f'unknown item: {name}')
        self.items[name] = self.items.get(name, 0) + qty

    def remove(self, name, qty=1):
        if name not in self.items:
            raise KeyError(name)
        self.items[name] -= qty
        if self.items[name] <= 0:
            del self.items[name]

    def total(self):
        return round(sum(self.prices[n] * q for n, q in self.items.items()), 2)

    def __str__(self):
        lines = [f'{q} x {n} = {self.prices[n] * q:.2f}' for n, q in sorted(self.items.items())]
        lines.append(f'TOTAL {self.total():.2f}')
        return '\n'.join(lines)

