from decimal import Decimal

class Money:
    def __init__(self, cents):
        if not isinstance(cents, int):
            raise TypeError('cents must be an integer')
        self.cents = cents

    @classmethod
    def from_amount(cls, amount):
        return cls(int(Decimal(str(amount)) * 100))

    def __add__(self, other):
        return Money(self.cents + other.cents)

    def __sub__(self, other):
        return Money(self.cents - other.cents)

    def allocate(self, *ratios):
        total = sum(ratios)
        if total <= 0:
            raise ValueError('ratios must sum to a positive value')
        shares = [self.cents * r // total for r in ratios]
        remainder = self.cents - sum(shares)
        for i in range(remainder):
            shares[i % len(shares)] += 1
        return [Money(s) for s in shares]

    def __str__(self):
        return f'{self.cents / 100:.2f}'

bill = Money.from_amount('100.00')
print([str(m) for m in bill.allocate(1, 1, 1)], bill + Money(250))

class GameScore:
    def __init__(self):
        self._scores = {}

    def add_player(self, name, score):
        if score < 0:
            raise ValueError('score must be non-negative')
        self._scores[name] = max(self._scores.get(name, 0), score)

    def top(self, n=3):
        ranked = sorted(self._scores.items(), key=lambda kv: (-kv[1], kv[0]))
        return ranked[:n]

    def rank_of(self, name):
        ranked = self.top(len(self._scores))
        for rank, (player, _) in enumerate(ranked, 1):
            if player == name:
                return rank
        raise KeyError(name)

    def __contains__(self, name):
        return name in self._scores

